namespace hanmo::resident {using namespace movement_detail;namespace {
bool same_ids(const std::vector<StableId>& a,const std::vector<StableId>& b){const std::set<StableId> x(a.begin(),a.end()),y(b.begin(),b.end());return x.size()==a.size()&&y.size()==b.size()&&x==y;}
StableId source_key(const SourceRef& r){return r.domain+":"+r.kind+":"+r.id;}
std::vector<StableId> inventory_ids(const CommonStore& common,const MilitaryArmyCompositionRead& actual){std::set<StableId> ids{actual.inventory_id};for(const auto& id:actual.named_actor_ids){const auto* actor=common.actor(id);if(!actor||actor->inventory_id.empty())fail("MilitaryEntryActorInventoryRequired",id);ids.insert(actor->inventory_id);}return {ids.begin(),ids.end()};}
}
NativeMilitaryTransportManifestHistoryRead::NativeMilitaryTransportManifestHistoryRead(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& cat,const MilitaryExactState& exact,const SpatialCarrierState& carriers,const MovementExactState& movement,const GroupMovementExecutionState& executions,const CharacterConditionSources& bodies,const CurrentMomentRead& clock,MilitaryMarchAuthorSelection author,const PopulationMilitaryState* population,const PopulationMilitaryCatalog* pc,ExactArithmeticBudget budget,const MilitaryFormationSourceRead* formations,const MilitaryReturnSourceRead* returns,const ExactTrainingPeriodRead* periods,const MilitaryFiniteReturnSourceRead* finite_returns):common_(c),military_(m),catalog_(cat),exact_(&exact),selected_{},carriers_(carriers),movement_(movement),executions_(executions),bodies_(bodies),clock_(clock),author_(std::move(author)),population_(population),population_catalog_(pc),budget_(budget),formations_(formations),returns_(returns),periods_(periods),finite_returns_(finite_returns){}
NativeMilitaryTransportManifestHistoryRead::NativeMilitaryTransportManifestHistoryRead(const CommonStore& c,const MilitaryState& m,const MilitaryCatalog& cat,MilitarySelectedHistoryRead selected,const SpatialCarrierState& carriers,const MovementExactState& movement,const GroupMovementExecutionState& executions,const CharacterConditionSources& bodies,const CurrentMomentRead& clock,MilitaryMarchAuthorSelection author,const PopulationMilitaryState* population,const PopulationMilitaryCatalog* pc,ExactArithmeticBudget budget,const MilitaryFormationSourceRead* formations,const MilitaryReturnSourceRead* returns,const ExactTrainingPeriodRead* periods,const MilitaryFiniteReturnSourceRead* finite_returns):common_(c),military_(m),catalog_(cat),exact_(selected.exact),selected_(selected),carriers_(carriers),movement_(movement),executions_(executions),bodies_(bodies),clock_(clock),author_(std::move(author)),population_(population),population_catalog_(pc),budget_(budget),formations_(formations),returns_(returns),periods_(periods),finite_returns_(finite_returns){}
Outcome<MilitaryArmyCompositionRead> NativeMilitaryTransportManifestHistoryRead::read_entry_composition(const TransportEntryManifestSource& entry)const{return guard<MilitaryArmyCompositionRead>([&]{world_stage_observation::observe_node({world_stage_observation::NodeMetric::api_attempt, "military.manifest.entry_composition", &common_.state(), nullptr, {"fact", "travel", "transport_entry_manifest", entry.id, 1}, {}, -1, entry.occurred_at.half_day_tick, true});
 const auto* head=common_.state().facts.find(entry.id);const auto* stored=executions_.entry_manifests.find(entry.id);const auto* execution=std::get_if<GroupMovementExecution>(&entry.execution);const auto* army=execution?std::get_if<ArmyCarrierRef>(&execution->carrier):nullptr;const auto* journey=execution?carriers_.journeys.find(execution->journey_id):nullptr;
 if(!stored||stored!=&entry||!head||head->domain!="travel"||head->kind!="transport_entry_manifest"||!army||!journey||entry.entry_ordinal<1||spatial_carrier_key(entry.manifest.carrier)!=spatial_carrier_key(execution->carrier)||entry.manifest.read_stamp)fail("MilitaryActualEntrySourceRequired",entry.id);
 const GroupMovementOpeningSource* opening=nullptr;for(const auto& row:executions_.openings.rows())if(row.second.journey_id==journey->journey_id){if(opening)fail("DuplicateMilitaryGroupOpening",entry.id);opening=&row.second;}
 const auto* origin=opening?std::get_if<ArmyCarrierRef>(&opening->carrier_origin):nullptr;const auto now=take(clock_.read_current_moment());if(!origin||origin->army_id!=army->army_id||!opening->military_order||take(compare_world_moments(opening->occurred_at,entry.occurred_at,budget_))>0||take(compare_world_moments(entry.occurred_at,now,budget_))>0)fail("MilitaryEntryOpeningRequired",entry.id);
 take(read_military_group_order_acceptance(common_,military_,catalog_,carriers_,movement_,executions_,bodies_,{"travel","group_movement_opening",opening->id},now,author_,budget_,formations_,finite_returns_));
 const MovementUnitState* unit=nullptr;for(const auto& row:movement_.units.rows())if(execution_key(row.second.execution)==execution_key(entry.execution)&&row.second.ordinal==entry.entry_ordinal-1){if(unit)fail("DuplicateGroupUnitOrdinal",entry.id);unit=&row.second;}const auto* effort=unit&&!unit->effort_basis_refs.empty()?movement_.exertion_bases.find(unit->effort_basis_refs.front().id):nullptr;
 if(!effort||effort->unit_ref!=unit->id||execution_key(effort->execution)!=execution_key(entry.execution)||take(compare_world_moments(effort->opened_at,entry.occurred_at,budget_))>0)fail("MilitaryEntryActualUnitRequired",entry.id);
 // Entry is the actual unconsumed start of this unit. Subsequent mutable prefix
 // state is never used to reconstruct the earlier anchor.
 MovementPrefixState frozen;frozen.basis=effort->actual_basis;frozen.cursor=effort->opened_cursor;frozen.lifecycle=MovementActive{};const auto anchor=take(read_movement_position(frozen,budget_));if(!take(same_spatial_anchor(anchor,entry.manifest.actual_anchor,budget_)))fail("MilitaryEntryOriginalAnchorMismatch",entry.id);
 for(const auto& span:unit->activity_spans)if(take(compare_world_moments(span.span.from,entry.occurred_at,budget_))<0)fail("MilitaryEntryAfterActualMotion",entry.id);
 const SourceRef entry_cut{"travel","transport_entry_manifest",entry.id};
 auto actual=(selected_?take(read_selected_military_army_composition_before(common_,military_,catalog_,*selected_,army->army_id,{"travel","transport_entry_manifest",entry.id},entry.occurred_at,now,population_,population_catalog_,budget_,formations_,returns_,periods_)):take(read_military_army_composition_before(common_,military_,catalog_,*exact_,army->army_id,{"travel","transport_entry_manifest",entry.id},entry.occurred_at,now,population_,population_catalog_,budget_,formations_,returns_,periods_)));
 if(!actual.prisoner_ids.empty())fail("MilitaryPrisonerSpatialHandoffRequired",army->army_id);
 if(entry.manifest.composition_revision!=actual.original_sources.composition_revision||entry.manifest.composition_revision!=take(read_group_composition_revision_before(common_,executions_,journey->journey_id,&entry_cut))||entry.manifest.manifest_revision<1||!same_ids(effort->actual_participants,opening->named_participants)||!same_ids(actual.named_actor_ids,opening->named_participants))fail("MilitaryEntryCompositionMismatch",entry.id);
 return actual;
});}
Outcome<std::vector<StableId>> NativeMilitaryTransportManifestHistoryRead::read_original_military_entry_inventory_ids(const TransportEntryManifestSource& entry)const{return guard<std::vector<StableId>>([&]{return inventory_ids(common_,take(read_entry_composition(entry)));});}
Outcome<TransportManifestDerivedTotals> NativeMilitaryTransportManifestHistoryRead::read_military_manifest_derived(const TransportEntryManifestSource& entry)const{return guard<TransportManifestDerivedTotals>([&]{
 const auto actual=take(read_entry_composition(entry));const auto& manifest=entry.manifest;
 if(!same_ids(actual.named_actor_ids,manifest.named_actor_refs)||inventory_ids(common_,actual)!=manifest.inventory_refs||!manifest.vehicle_refs.empty()||!manifest.civilian_population_refs.empty()||!manifest.vessel_placements.empty()||!entry.population_sources.empty()||manifest.at_tick!=entry.occurred_at.half_day_tick)fail("MilitaryEntryManifestScopeMismatch",entry.id);
 std::set<StableId> people(actual.named_actor_ids.begin(),actual.named_actor_ids.end());people.insert(actual.fit_member_ids.begin(),actual.fit_member_ids.end());people.insert(actual.wounded_member_ids.begin(),actual.wounded_member_ids.end());if(people.size()>std::size_t(std::numeric_limits<Integer>::max()))fail("MilitaryEntryPersonCountMismatch",entry.id);
 std::vector<StableId> force_ids;for(const auto& ref:manifest.military_force_refs){if(ref.domain!="military"||ref.kind!="military_unit")fail("MilitaryEntryForceSourceMismatch",entry.id);force_ids.push_back(ref.id);}if(!same_ids(force_ids,actual.unit_ids))fail("MilitaryEntryForceCoverageMismatch",entry.id);
 std::set<StableId> expected,provided;for(const auto& ref:actual.original_sources.authored_unit_sources)expected.insert(source_key(ref));for(const auto& source:actual.original_sources.original_changes)expected.insert(source_key(source.source_ref));
 const auto& execution=std::get<GroupMovementExecution>(entry.execution);const auto* journey=carriers_.journeys.find(execution.journey_id);expected.insert(source_key({"travel","movement_prefix",journey->movement_prefix_ref}));for(const auto& ref:manifest.source_refs){world_stage_observation::observe_node({world_stage_observation::NodeMetric::edge_traversal, "military.manifest.source_refs", &common_.state(), nullptr, {"fact", "travel", "transport_entry_manifest", entry.id, 1}, {"fact", ref.domain, ref.kind, ref.id, 0}, -1});if(!provided.insert(source_key(ref)).second)fail("MilitaryEntryDuplicateOriginalSource",entry.id);}if(provided!=expected)fail("MilitaryEntryOriginalSourceCoverage",entry.id);
 // Common's entry-bound original evidence is validated by its owner before this
 // leaf. Recompute only its physical sum; never read today's inventory payload.
 Integer weight=0;for(const auto& inventory:entry.inventory_sources){const auto part=take(inventory_entry_evidence_weight(inventory.entry_evidence));if(part<0||weight>std::numeric_limits<Integer>::max()-part)fail("MilitaryEntryWeightOverflow",entry.id);weight+=part;}
 return TransportManifestDerivedTotals{Integer(people.size()),0,weight,{}};
});}
Status NativeMilitaryTransportManifestHistoryRead::validate_military_manifest_history(const TransportEntryManifestSource& entry)const{return status([&]{
 const auto actual=take(read_military_manifest_derived(entry));
 if(actual.persons!=entry.manifest.persons||actual.working_crew!=entry.manifest.working_crew||actual.weight!=entry.manifest.weight||!actual.vessels.empty())fail("MilitaryEntryDerivedTotalsMismatch",entry.id);
});}
}
